def slug(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")
    return normalized[:48] or "gate"


def stage_from_headings(headings: dict[int, str]) -> str:
    return slug(headings.get(2, "unscoped"))


def discover_gates(content: str) -> list[dict]:
    headings: dict[int, str] = {}
    gates = []
    seen = set()
    for line_number, line in enumerate(content.splitlines(), start=1):
        heading = HEADING.match(line)
        if heading:
            level = len(heading.group(1))
            headings[level] = heading.group(2).strip()
            for key in tuple(headings):
                if key > level:
                    del headings[key]
            continue
        checkbox = CHECKBOX.match(line)
        if not checkbox:
            continue
        raw_label = checkbox.group(4).strip()
        metadata = {
            "kind": "generic", "verification_check": "",
            "capability": "", "pid_sensitive": False, "gate_key": "",
            "generation": 1, "supersedes": [],
        }
        label = raw_label
        while True:
            matched = False
            for marker in GATE_METADATA_MARKERS:
                found = marker.search(label)
                if not found:
                    continue
                value = found.group(1)
                if marker is GATE_KIND_MARKER:
                    metadata["kind"] = value
                elif marker is GATE_VERIFICATION_CHECK_MARKER:
                    metadata["verification_check"] = value
                elif marker is GATE_CAPABILITY_MARKER:
                    metadata["capability"] = value
                elif marker is GATE_PID_SENSITIVE_MARKER:
                    metadata["pid_sensitive"] = value == "true"
                elif marker is GATE_KEY_MARKER:
                    metadata["gate_key"] = value
                elif marker is GATE_GENERATION_MARKER:
                    metadata["generation"] = int(value)
                else:
                    metadata["supersedes"] = value.split(",")
                label = label[:found.start()].rstrip()
                matched = True
                break
            if not matched:
                break
        kind = metadata["kind"]
        if (
            "(only-if-frontend)" in label.lower()
            and FRONTEND_NOT_PRESENT_MARKER not in label.lower()
        ):
            metadata["capability"] = "frontend"
        if not label:
            raise GateError(f"Gate label is empty at TODO line {line_number}")
        if kind not in ALL_MACHINE_GATE_KINDS | {"generic"}:
            raise GateError(f"unsupported machine Gate kind at TODO line {line_number}: {kind}")
        path = " / ".join(headings[key] for key in sorted(headings))
        raw = f"{path}\0{label}".encode("utf-8")
        gate_id = f"{stage_from_headings(headings)}.{slug(label)}.{sha256_bytes(raw)[:8]}"
        gate_key = metadata["gate_key"] or gate_id
        if gate_id in seen:
            raise GateError(f"duplicate generated gate ID at TODO line {line_number}")
        seen.add(gate_id)
        gates.append({
            "gate_id": gate_id,
            "stage": stage_from_headings(headings),
            "label": label,
            "kind": kind,
            "verification_check": metadata["verification_check"],
            "capability": metadata["capability"],
            "pid_sensitive": metadata["pid_sensitive"],
            "gate_key": gate_key,
            "generation": metadata["generation"],
            "supersedes": metadata["supersedes"],
            "line": line_number,
        })
    if not gates:
        raise GateError("session TODO contains no checkboxes")
    return gates


